records.text:
$defs = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')) | ConvertFrom-Json
$results=@()
foreach($c in $defs) {
 $Error.Clear()
 $out = . ([scriptblock]::Create($c.input)) | Out-String -Width 220
 $errs=@($Error | ForEach-Object { [pscustomobject]@{id=$_.FullyQualifiedErrorId;message=$_.Exception.Message} })
 $results += [pscustomobject]@{id=$c.id;output=$out;errors=$errs}
}
$results | ConvertTo-Json -Depth 7
